.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
ind<-read.csv('outputs/stage6_foxp2_gnomad_narrow_variants.csv');all<-read.csv('work/stage6_foxp2_susie_aligned.csv');d<-all[match(ind$rs,all$rs),];stopifnot(nrow(d)==1257,all(d$rs==ind$rs));p<-nrow(d)
readR<-function(pop){x<-matrix(readBin(paste0('work/stage6_foxp2_gnomad_',pop,'_narrow_ld.bin'),'double',n=p*p,size=8,endian='little'),p,p);dimnames(x)<-list(d$rs,d$rs);e<-eigen(x,symmetric=TRUE);stopifnot(min(e$values)>-1e-8);attr(x,'eigen')<-e;x}
Rn<-readR('nfe');Rf<-readR('fin');traits<-c('MVP_effN','MVP_totalN','HFRS');ns<-c(253769,408138,500737);zs<-list(d$mvp_z_anchor,d$mvp_z_anchor,d$hfrs_z_anchor);fits<-list();reports<-list()
for(i in seq_along(traits)){
 name<-traits[i];z<-zs[[i]];names(z)<-d$rs;R<-if(name=='HFRS')Rf else Rn;pop<-if(name=='HFRS')'gnomAD_FIN' else 'gnomAD_NFE';lambda<-estimate_s_rss(z,R,n=ns[i]);set.seed(42);f<-susie_rss(z=z,R=R,n=ns[i],L=10,estimate_residual_variance=FALSE,max_iter=500,coverage=.95);fits[[name]]<-f;cs<-f$sets$cs;sets<-data.frame(component=integer(),size=integer(),lead=character(),lead_pip=numeric(),min_abs_corr=numeric());if(length(cs)>0)for(k in seq_along(cs)){id<-cs[[k]];lead<-id[which.max(f$pip[id])];sets<-rbind(sets,data.frame(component=f$sets$cs_index[k],size=length(id),lead=d$rs[lead],lead_pip=f$pip[lead],min_abs_corr=f$sets$purity[k,'min.abs.corr']))};write.csv(sets,paste0('outputs/stage6_foxp2_gnomad_',name,'_candidate_sets.csv'),row.names=FALSE);reports[[i]]<-data.frame(trait=name,reference=pop,n_variants=p,working_n=ns[i],estimated_lambda=lambda,converged=f$converged,iterations=f$niter,n_sets=length(cs),max_pip=max(f$pip));cat(name,'lambda',lambda,'sets',length(cs),'converged',f$converged,'\n');flush.console()
}
write.csv(do.call(rbind,reports),'outputs/stage6_foxp2_gnomad_ancestry_matched_diagnostics.csv',row.names=FALSE);saveRDS(fits,'work/stage6_foxp2_gnomad_ancestry_matched_fits.rds')
results<-list();for(nchoice in c('effN','totalN'))for(p12 in c(1e-6,1e-5,5e-5)){m<-fits[[paste0('MVP_',nchoice)]];if(length(m$sets$cs)==0||length(fits$HFRS$sets$cs)==0)next;s<-as.data.frame(coloc.susie(m,fits$HFRS,p1=1e-4,p2=1e-4,p12=p12)$summary);s$mvp_n_assumption<-nchoice;s$p12<-p12;results[[length(results)+1]]<-s};if(length(results))write.csv(do.call(rbind,results),'outputs/stage6_foxp2_gnomad_ancestry_matched_coloc.csv',row.names=FALSE)
